query Metrics($query: MetricsQueryInput!) {
  metrics(query: $query) {
    unit
    labels {
      field
      value
      __typename
    }
    values {
      time
      value
      __typename
    }
    parameters {
      quantile
      __typename
    }
    __typename
  }
}

mutation DeleteService($id: String!, $confirm: String) {
  deleteService(id: $id, confirm: $confirm)
}
